        _ = parser.deinit();
        }
        _ = (blk_catch_0: { break :blk_catch_0 ((parser.processDoc()) catch |e| { _ = &e; break :blk_catch_0 (switch (e) {
error.OutOfMemory => {
return error.OutOfMemory;
